#!/usr/bin/env python3
"""Deterministic HTML preview. No image generation, keyboard hook or network."""
import html,json
from pathlib import Path
R=Path(__file__).parent

def main():
 d=json.loads((R/'DESIGN_R6.json').read_text());pos=d['position_map'];esc=lambda x:html.escape(str(x),quote=True)
 names={'BASIC':'בסיס','NUMBERS':'מספרים','MENUS':'תפריטים','TOOLS':'מקשי F וכלים','NAV':'ניווט וסימנים'}
 labels={'Backspace':'Backsp','Left Bracket':'[','Right Bracket':']','Semicolon':';','Apostrophe':"'",'Backslash':'\\','Slash':'/','Backtick':'`','Minus':'−','Equals':'=','Comma':',','Period':'.','Up Arrow':'↑','Down Arrow':'↓','Left Arrow':'←','Right Arrow':'→','Page Up':'PgUp','Page Down':'PgDn','Caps Lock':'Caps Lock'}
 sections=[];contracts=[]
 def button(fam,l,vp,key):
  n=pos[vp];assert n!=19
  cls='key';txt=labels.get(key,key);small=''
  if key=='UNASSIGNED':cls+=' empty';txt='—'
  elif key.startswith('LAYER:'):
   cls+=' layer-key';target=key[6:] if l=='BASIC' else 'BASIC';txt=target;small='החזק' if l=='BASIC' else 'שחרור לבסיס'
  elif key in ['Ctrl','Shift','Alt','Esc','Space','Enter']:cls+=' anchor'
  group='little' if vp=='L3' else 'thumb' if vp.startswith(('TH_','ST_')) else ['little','ring','middle','index'][int(vp[-1])-1]
  attrs=''
  if vp.startswith('R') and 'C' in vp:attrs=f' style="grid-row:{vp[1]};grid-column:{vp[-1]}"'
  details=names[l]+' · #'+str(n)+' · '+('לא משויך' if key=='UNASSIGNED' else key)
  contracts.append({'family':fam,'layer':l,'button_id':n,'position':vp,'output':key,'finger_hypothesis':group})
  return f'<button class="{cls}" data-native-id="{n}" data-position="{vp}" data-output="{esc(key)}" data-group="{group}" aria-label="{esc(details)}" title="{esc(details)}"{attrs}><span class="id">{n}</span><strong dir="ltr">{esc(txt)}</strong><small>{esc(small)}</small></button>'
 for fam,v in d['variants'].items():
  for l,m in v['maps'].items():
   fingers=''.join(button(fam,l,p,k) for p,k in m.items() if p.startswith('R') and 'C' in p)
   side=button(fam,l,'L3',m['L3'])
   thumb=''.join(button(fam,l,p,m[p]) for p in ['TH_U','TH_L','TH_C','TH_R','TH_D','ST_RU','ST_RD','ST_D'])
   sections.append(f'<section class="layer-view" data-family="{fam}" data-layer="{l}" hidden><header class="map-title"><b dir="ltr">{fam} · {l}</b><span>{names[l]}</span></header><div class="map-body" dir="ltr"><div class="little-side">{side}</div><div class="fingers">{fingers}</div><div class="thumb">{thumb}</div></div><footer class="map-footer">29 כפתורים דיגיטליים · פריסת עזר קומפקטית · שיוכי המשחק אינם מוצגים באב־טיפוס</footer></section>')
 template='''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'"><title>Azeron R6 — אב־טיפוס Overlay</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf1f6;color:#183045;font:16px/1.6 system-ui,Arial,sans-serif}main{max-width:1140px;padding:25px 22px 48px;margin:auto}h1{font-size:29px;line-height:1.3;margin:0 0 14px}h2{font-size:20px;margin:0 0 9px}.intro{max-width:960px}p{margin:8px 0 15px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:15px;background:#fff;border:1px solid #b8c7d6;border-radius:10px;margin:18px 0}select,button,input{font:inherit}select,.text-button{border:1px solid #8096aa;border-radius:6px;padding:7px 10px;background:white;color:#142e44;cursor:pointer}label{display:flex;gap:7px;align-items:center}#layer{min-width:140px}.preview-scroll{overflow:auto;padding:15px 4px 25px}.stage{width:960px;max-width:none;margin:auto;transform-origin:top left;--bg:rgba(24,29,44,.95)}.layer-view{border-radius:13px;background:var(--bg);border:1px solid #667389;box-shadow:0 10px 28px #17263722;padding:20px 17px 13px;color:#f5f5dc;min-height:468px}.layer-view[hidden]{display:none!important}.map-title{display:flex;align-items:center;justify-content:space-between;padding:0 5px 16px;font-size:22px;gap:18px}.map-title span{font-size:16px;color:#bdd4e3}.map-body{display:grid;grid-template-columns:74px 516px 272px;gap:18px;align-items:start;justify-content:center}.fingers{display:grid;grid-template-columns:repeat(4,123px);grid-template-rows:repeat(5,64px);gap:7px}.key{padding:10px 4px 5px;position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;height:64px;width:100%;border:1px solid #748294;border-radius:7px;background:#222839;color:#fbffdf;cursor:pointer;text-align:center;line-height:1.1;min-width:0}.key strong{font-size:21px;font-weight:700;overflow-wrap:anywhere;max-width:100%}.key small{font-size:11px;height:11px;margin-top:6px;color:#c6d5e2}.key .id{position:absolute;top:4px;left:6px;font-size:10px;color:#92a4b8}.key.empty{background:#1b2030;border:1px dashed #506071;color:#8190a5}.key.empty strong{font-weight:400}.key.layer-key{background:#203949;border-color:#5eb6c3}.key.layer-key strong{font-size:16px;color:#e9fc6b}.key.anchor{border-color:#a2995d}.key:focus-visible{outline:3px solid #fff36c;outline-offset:2px}.little-side{padding-top:142px}.little-side .key{height:64px}.thumb{display:grid;grid-template-columns:repeat(3,84px);grid-template-rows:repeat(5,64px);gap:7px;border-left:1px solid #465064;padding-left:6px}.thumb [data-position="TH_U"]{grid-row:1;grid-column:2}.thumb [data-position="TH_L"]{grid-row:2;grid-column:1}.thumb [data-position="TH_C"]{grid-row:2;grid-column:2}.thumb [data-position="TH_R"]{grid-row:2;grid-column:3}.thumb [data-position="TH_D"]{grid-row:3;grid-column:2}.thumb [data-position="ST_RU"]{grid-row:3;grid-column:3}.thumb [data-position="ST_RD"]{grid-row:4;grid-column:3}.thumb [data-position="ST_D"]{grid-row:4;grid-column:1}.thumb strong{font-size:18px}.map-footer{text-align:center;color:#afc2d1;font-size:11px;border-top:1px solid #444e63;margin-top:15px;padding-top:9px}.no-ids .id{display:none}.notes{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:15px}.note{background:white;padding:18px;border:1px solid #bfccda;border-radius:9px}.warning{background:#fff4dd;border-color:#c79b59}.details{font-size:14px;padding:12px 15px;background:#e0e9f2;border-radius:7px;min-height:53px}code{direction:ltr;unicode-bidi:isolate;font:14px Consolas,monospace}body.clean .intro,body.clean .notes,body.clean .details{display:none}body.clean{background:transparent}body.clean .controls{background:#fffdf3}body.clean main{max-width:1040px}a{color:#0f5b80}@media(max-width:760px){main{padding:20px 12px}.notes{grid-template-columns:1fr}h1{font-size:25px}.stage{margin:0}}@media print{.intro,.controls,.notes,.details{display:none}.preview-scroll{overflow:visible}.stage{zoom:.7}.layer-view{break-inside:avoid}}
</style></head><body><main><div class="intro"><h1>R6: בסיס תצוגה מדויק לפני יצירת תמונות</h1><p>בחר משפחת פרופילים ושכבה. המסגרת מציגה את הפלט שנכתב בקבצים החדשים; היא אינה מפעילה את Azeron ואינה מזהה שכבה חיה.</p><p><strong>אין ציור ג׳ויסטיק. כפתור האצבע המורה ימינה — מספר 19 — מוסתר ושמור לתוכנה החיצונית.</strong> כל 29 הכפתורים הדיגיטליים האחרים קיימים, כולל הזרת וצדה, גם כאשר הם ריקים. אזור האגודל כווץ בלי לשנות את מספרי הכפתורים; זו פריסת עזר, לא צילום של התוכנה.</p></div><div class="controls"><label>משפחה <select id="family"><option value="COMPACT">COMPACT — ארבע שכבות</option><option value="SPARSE" selected>SPARSE — חמש שכבות</option></select></label><label>שכבה <select id="layer"></select></label><label><input type="checkbox" id="ids" checked> מספרי כפתורים</label><label>אטימות <input id="opacity" type="range" min="50" max="100" value="95"></label><button class="text-button" id="clean">תצוגה נקייה / חזרה</button></div><div class="preview-scroll"><div id="stage" class="stage">__MAPS__</div></div><div class="details" id="detail" role="status">לחיצה על כפתור בתרשים מציגה את מספרו ופלטו בלבד — אינה שולחת לחיצה למערכת.</div><div class="notes"><article class="note"><h2>היגיון התצוגה</h2><p>מפה אחת גדולה בכל פעם, ולא ארבע מפות ממוזערות. ארבע עמודות האצבעות נשארות קבועות; מיקום ריק לא גורם לתזוזת השכנים. כפתור 36 נמצא בצד הזרת, וכפתור 37 בשורה התחתונה שלה.</p><p>כותרת השכבה מספקת הקשר, צבע אינו הסימן היחיד. התוויות קצרות; הפלט המדויק ומספר הכפתור מופיעים גם בתיאור הנגיש של כל תא.</p></article><article class="note warning"><h2>לפני תמונות עם פעולות משחק</h2><p>לכל משחק יידרש חיבור מפורש: כפתור + שכבה → קוד מקלדת → פעולה בהקשר ובגרסה המתאימים. אב־הטיפוס אינו ממציא פעולה כאשר אין מקור.</p><p>השמות MENUS ו־NAV מתארים דרך זכירה של הבנק. הם אינם הוכחה שכל מקש בבנק פותח תפריט בכל משחק. הקובץ אינו תמונת Overlay מוכנה ואינו מתחבר לתוכנת התצוגה החיצונית.</p></article></div></main><script>
const names=__NAMES__,families=__FAMILIES__;
const family=document.getElementById('family'),layer=document.getElementById('layer');
function choose(){document.querySelectorAll('.layer-view').forEach(s=>s.hidden=!(s.dataset.family===family.value&&s.dataset.layer===layer.value));document.getElementById('detail').textContent='המשפחה '+family.value+' · '+names[layer.value]+'. לחיצה על תא היא בדיקת תצוגה בלבד.';}
function changeFamily(){const previous=layer.value;layer.replaceChildren();families[family.value].forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=names[k]+' / '+k;layer.appendChild(o)});layer.value=families[family.value].includes(previous)?previous:'BASIC';choose();}
family.addEventListener('change',changeFamily);layer.addEventListener('change',choose);
document.getElementById('ids').addEventListener('change',e=>document.getElementById('stage').classList.toggle('no-ids',!e.target.checked));
document.getElementById('opacity').addEventListener('input',e=>document.getElementById('stage').style.setProperty('--bg','rgba(24,29,44,'+(Number(e.target.value)/100)+')'));
document.getElementById('clean').addEventListener('click',()=>document.body.classList.toggle('clean'));
document.querySelectorAll('.key').forEach(b=>b.addEventListener('click',()=>{document.getElementById('detail').textContent='כפתור '+b.dataset.nativeId+' · '+b.dataset.position+' · '+(b.dataset.output==='UNASSIGNED'?'ריק במכוון':b.dataset.output)+' · אין כאן פעולה של משחק מאומתת.'}));changeFamily();
</script></body></html>'''
 text=template.replace('__MAPS__',''.join(sections)).replace('__NAMES__',json.dumps(names,ensure_ascii=False)).replace('__FAMILIES__',json.dumps({f:list(v['maps']) for f,v in d['variants'].items()}))
 (R/'Azeron_R6_Overlay_Prototype_HE.html').write_text(text,encoding='utf-8')
 (R/'OVERLAY_GEOMETRY_CONTRACT.json').write_text(json.dumps({'visible_per_layer':29,'hidden_reserved_native_ids':[19],'hidden_stick_input':24,'maps':contracts,'function':'keys-only prototype, not game-action evidence or runtime layer detector'},ensure_ascii=False,indent=2)+'\n')
 print('Layer views',len(sections),'visible controls',len(contracts))
if __name__=='__main__':main()
